{"content": [{"type": "text", "text": "{"status":"success","path":"data_pools/schemas/characters.schema.json","content":"{\n  \"$schema\": \"http://json-schema.org/draft-07/schema#\",\n  \"$id\": \"characters.schema.json\",\n  \"title\": \"小说人物设计\",\n  \"description\": \"人物一致性的参考依据，避免角色崩坏\",\n  \"type\": \"object\",\n  \"required\": [\"main_characters\"],\n  \"properties\": {\n    \"main_characters\": {\n      \"type\": \"array\",\n      \"description\": \"主角/核心角色数组\",\n      \"minItems\": 1,\n      \"items\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"name\",\n          \"role\",\n          \"traits\",\n          \"overt_motivation\",\n          \"covert_motivation\",\n          \"secret_fear\"\n        ],\n        \"properties\": {\n          \"name\": {\n            \"type\": \"string\",\n            \"description\": \"角色姓名\"\n          },\n          \"role\": {\n            \"type\": \"string\",\n            \"enum\": [\"protagonist\", \"deuteragonist\"],\n            \"description\": \"角色类型：protagonist=第一主角，deuteragonist=第二主角\"\n          },\n          \"identity\": {\n            \"type\": \"string\",\n            \"description\": \"身份职业/社会角色\"\n          },\n          \"traits\": {\n            \"type\": \"array\",\n            \"description\": \"核心性格特质关键词（3-5个）\",\n            \"items\": {\n              \"type\": \"string\"\n            },\n            \"minItems\": 3,\n            \"maxItems\": 5\n          },\n          \"overt_motivation\": {\n            \"type\": \"string\",\n            \"description\": \"显性动机（表面目标）\"\n          },\n          \"covert_motivation\": {\n            \"type\": \"string\",\n            \"description\": \"隐性动机（深层需求）\"\n          },\n          \"secret_fear\": {\n            \"type\": \"string\",\n            \"description\": \"秘密恐惧（内心脆弱点）\"\n          },\n          \"misperception_of_other\": {\n            \"type\": \"string\",\n            \"description\": \"对其他主角的错位认知\"\n          },\n          \"hidden_connection\": {\n            \"type\": \"string\",\n            \"description\": \"与其他角色的隐藏连接\"\n          }\n        }\n      }\n    },\n    \"supporting_characters\": {\n      \"type\": \"array\",\n      \"description\": \"配角/次要角色数组\",\n      \"items\": {\n        \"type\": \"object\",\n        \"required\": [\"name\", \"function\"],\n        \"properties\": {\n          \"name\": {\n            \"type\": \"string\",\n            \"description\": \"配角姓名\"\n          },\n          \"function\": {\n            \"type\": \"string\",\n            \"enum\": [\"助力\", \"阻碍\", \"反转点\"],\n            \"description\": \"对主角的作用类型\"\n          },\n          \"identity\": {\n            \"type\": \"string\",\n            \"description\": \"配角身份\"\n          },\n          \"description\": {\n            \"type\": \"string\",\n            \"description\": \"配角简要描述\"\n          }\n        }\n      }\n    },\n    \"relationship_dynamics\": {\n      \"type\": \"string\",\n      \"description\": \"角色关系动态描述\"\n    }\n  }\n}\n","size":2564}"}], "structuredContent": {"status": "success", "path": "data_pools/schemas/characters.schema.json", "content": "{
